local SconceMaker = {}
local PRODUCTS = {
    wall_bracket = { name = "Zidni nosilec", ironCost = 1, time = 1, cost = 6, lightRadius = 3, description = "Preprost železni zidni nosilec za luč." },
    candle_sconce = { name = "Svečnik na sconce", ironCost = 1, time = 2, cost = 18, lightRadius = 5, prestige = 1, description = "Zidni svečnik z majhnim okrasjem." },
    torch_holder = { name = "Nosilec za baklo", ironCost = 2, time = 3, cost = 40, lightRadius = 8, prestige = 2, description = "Težek nosilec za bakle na hodnikih." },
    brass_sconce = { name = "Medeninasta sconce", brassCost = 2, time = 4, cost = 85, lightRadius = 10, prestige = 5, description = "Medeninasta sconca z bleščečim leskom." },
    silver_sconce = { name = "Srebrna sconce", silverCost = 2, ironCost = 1, time = 5, cost = 170, lightRadius = 12, prestige = 9, happiness = 1, description = "Srebrna zidna luč za plemiške dvorane." },
    royal_chandelier_sconce = { name = "Kraljevski sconce-luster", goldCost = 2, silverCost = 2, brassCost = 2, time = 8, cost = 450, lightRadius = 18, prestige = 22, happiness = 4, description = "Veliki zidni luster z zlatimi in srebrnimi detajli." },
}
local BUILDINGS = {
    workshop = { name = "Sconcarska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    forge = { name = "Sconcarska kovačija", cost = { gold = 650, wood = 200, stone = 150 }, upkeep = 16, qualityBonus = 15 },
    polishing_room = { name = "Polirnica", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 26, qualityBonus = 22 },
    royal_sconce_atelier = { name = "Kraljevski atelje sconcev", cost = { gold = 3200, wood = 400, stone = 500, gold = 30 }, upkeep = 62, qualityBonus = 36, prestigeBonus = 17 },
}
SconceMaker.ironStock = 18; SconceMaker.brassStock = 6; SconceMaker.silverStock = 4; SconceMaker.goldStock = 3
SconceMaker.productStock = {}; SconceMaker.buildings = {}; SconceMaker.maker = nil; SconceMaker.activeMaking = {}; SconceMaker.totalProducts = 0; SconceMaker.dayTimer = 0
function SconceMaker.init() SconceMaker.ironStock=18; SconceMaker.brassStock=6; SconceMaker.silverStock=4; SconceMaker.goldStock=3; SconceMaker.productStock={}; SconceMaker.buildings={}; SconceMaker.maker=nil; SconceMaker.activeMaking={}; SconceMaker.totalProducts=0; SconceMaker.dayTimer=0; print("[SconceMaker] Royal Sconce & Wall Light System initialized (6 products, 4 buildings)") end
function SconceMaker.hireMaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SconceMaker.maker={name=n or ("Sconcar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sconcar najet: %s (spretnost: %d)",SconceMaker.maker.name,s),"success") end; return true end
function SconceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SconceMaker.build(id) local ok,e=SconceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SconceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SconceMaker.getQualityBonus() local b=0; for _,bd in ipairs(SconceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SconceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SconceMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and SconceMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and SconceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SconceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #SconceMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SconceMaker.maker then return false,"Potreben sconcar" end; return true end
function SconceMaker.make(pt,qty) qty=qty or 5; local ok,e=SconceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SconceMaker.ironStock=SconceMaker.ironStock-d.ironCost*qty end; if d.brassCost then SconceMaker.brassStock=SconceMaker.brassStock-d.brassCost*qty end; if d.silverCost then SconceMaker.silverStock=SconceMaker.silverStock-d.silverCost*qty end; if d.goldCost then SconceMaker.goldStock=SconceMaker.goldStock-d.goldCost*qty end; local t=d.time; if SconceMaker.maker then t=math.max(1,t-math.floor(SconceMaker.maker.skill/15)) end; table.insert(SconceMaker.activeMaking,{id="sconce_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,lightRadius=d.lightRadius or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SconceMaker.completeMaking(m) local q=1.0+(SconceMaker.getQualityBonus()/100); if SconceMaker.maker then q=q+(SconceMaker.maker.skill/200) end; q=math.min(2.0,q); SconceMaker.productStock[m.productType]=(SconceMaker.productStock[m.productType] or 0)+m.quantity; SconceMaker.totalProducts=SconceMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SconceMaker.maker then SconceMaker.maker.itemsMade=SconceMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then SconceMaker.maker.skill=math.min(100,SconceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sconce izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function SconceMaker.update(dt) if not _G.state then return end; SconceMaker.dayTimer=SconceMaker.dayTimer+dt; if SconceMaker.dayTimer>=30 then SconceMaker.dayTimer=0; for i=#SconceMaker.activeMaking,1,-1 do local m=SconceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SconceMaker.completeMaking(m); table.remove(SconceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SconceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SconceMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SconceMaker.getStats() return {ironStock=SconceMaker.ironStock,brassStock=SconceMaker.brassStock,silverStock=SconceMaker.silverStock,goldStock=SconceMaker.goldStock,productStock=SconceMaker.productStock,numBuildings=#SconceMaker.buildings,hasMaker=SconceMaker.maker~=nil,makerName=SconceMaker.maker and SconceMaker.maker.name or "—",makerSkill=SconceMaker.maker and SconceMaker.maker.skill or 0,activeMaking=#SconceMaker.activeMaking,totalProducts=SconceMaker.totalProducts} end
return SconceMaker
